CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, role TEXT NOT NULL DEFAULT 'customer', full_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, phone TEXT, password_hash TEXT NOT NULL, email_verified_at TEXT, is_active INTEGER NOT NULL DEFAULT 1, last_login_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, ip_address TEXT NOT NULL, succeeded INTEGER NOT NULL DEFAULT 0, attempted_at TEXT NOT NULL DEFAULT (datetime('now','localtime')));
CREATE TABLE categories (id INTEGER PRIMARY KEY AUTOINCREMENT, parent_id INTEGER REFERENCES categories(id), name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT, image_file TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, category_id INTEGER NOT NULL REFERENCES categories(id), sku TEXT UNIQUE, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, short_description TEXT, description TEXT, price NUMERIC NOT NULL CHECK (price >= 0), compare_at_price NUMERIC, stock_quantity INTEGER NOT NULL DEFAULT 0 CHECK (stock_quantity >= 0), low_stock_threshold INTEGER NOT NULL DEFAULT 5, is_featured INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1, is_customizable INTEGER NOT NULL DEFAULT 0, custom_label TEXT, custom_max_length INTEGER NOT NULL DEFAULT 100 CHECK (custom_max_length BETWEEN 10 AND 500), custom_required INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_images (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), file_name TEXT NOT NULL UNIQUE, alt_text TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_primary INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inventory_movements (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL, quantity_change INTEGER NOT NULL, stock_after INTEGER NOT NULL, reason TEXT NOT NULL, order_id INTEGER, user_id INTEGER, note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admin_activity_log (id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, details TEXT, ip_address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (setting_key TEXT PRIMARY KEY, setting_value TEXT NOT NULL DEFAULT '', value_type TEXT NOT NULL DEFAULT 'text', label TEXT NOT NULL, description TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_addresses (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, label TEXT NOT NULL DEFAULT 'Home', recipient_name TEXT NOT NULL, phone TEXT NOT NULL, address_line1 TEXT NOT NULL, address_line2 TEXT, city TEXT NOT NULL, district TEXT NOT NULL, postal_code TEXT, is_default INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE carts (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cart_items (id INTEGER PRIMARY KEY AUTOINCREMENT, cart_id INTEGER NOT NULL, product_id INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 99), customization_text TEXT, added_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(cart_id, product_id));
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, order_number TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', customer_name TEXT NOT NULL, customer_email TEXT NOT NULL, customer_phone TEXT NOT NULL, recipient_name TEXT NOT NULL, recipient_phone TEXT NOT NULL, address_line1 TEXT NOT NULL, address_line2 TEXT, city TEXT NOT NULL, district TEXT NOT NULL, postal_code TEXT, delivery_notes TEXT, subtotal NUMERIC NOT NULL, delivery_fee NUMERIC NOT NULL DEFAULT 0, discount_amount NUMERIC NOT NULL DEFAULT 0, total_amount NUMERIC NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')), updated_at TEXT DEFAULT CURRENT_TIMESTAMP, CHECK (abs(total_amount - (subtotal + delivery_fee - discount_amount)) < 0.001));
CREATE TABLE order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, product_id INTEGER, product_name TEXT NOT NULL, product_sku TEXT, unit_price NUMERIC NOT NULL, quantity INTEGER NOT NULL CHECK (quantity >= 1), line_total NUMERIC NOT NULL, customization_text TEXT, UNIQUE(order_id, product_id), CHECK (abs(line_total - unit_price * quantity) < 0.001));
CREATE TABLE order_status_history (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, from_status TEXT, to_status TEXT NOT NULL, changed_by INTEGER, note TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')), CHECK (from_status IS NULL OR from_status <> to_status));
CREATE TABLE payments (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL UNIQUE, method TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', amount NUMERIC NOT NULL, reference TEXT, paid_at TEXT, refunded_at TEXT, recorded_by INTEGER, admin_note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL CHECK (purpose IN ('verify_email','reset_password')), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')));
CREATE TABLE email_log (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, order_id INTEGER, template TEXT NOT NULL, recipient TEXT NOT NULL, subject TEXT NOT NULL, transport TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('sent','saved','skipped','failed')), error TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')));
CREATE TABLE banners (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, subtitle TEXT, button_text TEXT, link_url TEXT, image_file TEXT NOT NULL, show_text INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1, starts_on TEXT, ends_on TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (starts_on IS NULL OR ends_on IS NULL OR ends_on >= starts_on));
CREATE TABLE wishlist_items (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')), PRIMARY KEY (user_id, product_id));
CREATE TABLE product_reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, order_id INTEGER, rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5), comment TEXT, reviewer_name TEXT NOT NULL, is_visible INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, product_id));
